import java.util.*;
import java.io.*;

public class Main {
    static final int MAXN = 202;
    static final int INF = 0x3f3f3f3f;
    static int[][] f = new int[MAXN][MAXN];
    static int[][] c = new int[MAXN][MAXN];
    static int[] p = new int[MAXN];
    static int[] d = new int[MAXN];
    static int[][] gridA = new int[11][11];
    static int[][] gridB = new int[11][11];
    static int n, t, bi, bj;
    static int[][] mat = new int[101][101];
    static List<Integer> ca = new ArrayList<>();
    static List<Integer> cb = new ArrayList<>();
    static List<Integer> cc = new ArrayList<>();
    static int[][] directions = {{0,1},{0,-1},{1,0},{-1,0}};
    static final int INF_VAL = 1000000000;

    public static int max_flow(int n, int s, int e) {
        int total = 0;
        while (true) {
            Arrays.fill(p, -1);
            Arrays.fill(d, 0);
            d[s] = INF;
            Queue<Integer> q = new LinkedList<>();
            q.offer(s);
            while (!q.isEmpty() && p[e] < 0) {
                int u = q.poll();
                for (int v = 0; v < n; v++) {
                    if (p[v] < 0 && c[u][v] - f[u][v] > 0) {
                        p[v] = u;
                        d[v] = Math.min(d[u], c[u][v] - f[u][v]);
                        q.offer(v);
                    }
                }
            }
            if (p[e] < 0) break;
            for (int v = e; v != s; v = p[v]) {
                f[p[v]][v] += d[e];
                f[v][p[v]] -= d[e];
            }
            total += d[e];
        }
        return total;
    }

    public static void search(int A, int B, int[] visited, boolean check) {
        Queue<int[]> q = new LinkedList<>();
        int nCells = n * n;
        visited[A * n + B] = 0;
        q.offer(new int[]{A, B});
        while (!q.isEmpty()) {
            int[] p = q.poll();
            int pIdx = p[0] * n + p[1];
            int dis = visited[pIdx];
            if (check && (mat[bi * n + bj][pIdx] <= dis || t <= dis)) {
                if (mat[bi * n + bj][pIdx] < dis || t < dis) {
                    visited[pIdx] = INF_VAL + 1;
                }
                continue;
            }
            for (int d = 0; d < 4; d++) {
                int ni = p[0] + directions[d][0];
                int nj = p[1] + directions[d][1];
                if (ni < 0 || nj < 0 || ni >= n || nj >= n) continue;
                if (gridB[ni][nj] < '0' || gridB[ni][nj] > '9') continue;
                int qIdx = ni * n + nj;
                if (visited[qIdx] != INF_VAL) continue;
                visited[qIdx] = dis + 1;
                q.offer(new int[]{ni, nj});
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        t = Integer.parseInt(st.nextToken());
        for (int i = 0; i < n; i++) {
            st = new StringTokenizer(br.readLine());
            for (int j = 0; j < n; j++) {
                gridA[i][j] = st.nextToken().charAt(0);
            }
        }
        for (int i = 0; i < n; i++) {
            st = new StringTokenizer(br.readLine());
            for (int j = 0; j < n; j++) {
                gridB[i][j] = st.nextToken().charAt(0);
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (gridA[i][j] == 'Z') {
                    bi = i;
                    bj = j;
                }
            }
        }
        for (int[] row : mat) {
            Arrays.fill(row, INF_VAL);
        }
        int[] visited = new int[n * n];
        Arrays.fill(visited, -1);
        search(bi, bj, visited, false);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (gridA[i][j] >= '1' && gridA[i][j] <= '9') {
                    Arrays.fill(visited, -1);
                    search(i, j, visited, true);
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (gridA[i][j] >= '0' && gridA[i][j] <= '9') {
                    int pIdx = i * n + j;
                    c[pIdx + 2 + n * n][1] = gridA[i][j] - '0';
                }
            }
        }
        int z = bi * n + bj;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (gridB[i][j] >= '0' && gridB[i][j] <= '9') {
                    int pIdx = i * n + j;
                    c[0][pIdx + 2] = gridB[i][j] - '0';
                    for (int k = 0; k < ca.size(); k++) {
                        int ii = ca.get(k);
                        int jj = cb.get(k);
                        int qIdx = ii * n + jj;
                        if (mat[pIdx][qIdx] < INF_VAL)
                            c[pIdx + 2][qIdx + 2 + n * n] = INF_VAL;
                    }
                }
            }
        }
        System.out.println(max_flow(2 + n * n, 0, 1));
    }
}
